mapper.select:
SELECT ast80_relate_appr_id                                                          AS relate_appr_id
     , ast80_appr_id                                                                 AS appr_id
     , b.apr01_status_cd                                                             AS status_code
     , f_cdnm('AprStatusCode', b.apr01_status_cd, ast80_company_id, b.apr01_reg_date) AS status_name
  FROM ast80_relate_appr
       LEFT OUTER JOIN apr01_appr b ON ast80_appr_id = apr01_appr_id
 WHERE ast80_company_id = #{companyId}
   AND ast80_date       = #{date}
   AND ast80_link_cd    = #{linkCode}

mapper.update:
UPDATE ast80_relate_appr
   SET ast80_appr_id = #{apprId}
 WHERE ast80_relate_appr_id = #{relateApprId}
